# ---- 奈良 ----
s("東大寺 大仏殿","tower",1709,"奈良市","","世界最大級の木造建築","現在の建物は江戸時代の再建で、創建時より少し小さい。柱の一本一本に、太い木材をつなぎ合わせて使っている。",34.6890,135.8398,"国宝")
s("東大寺 南大門","tower",1203,"奈良市","重源・陳和卿","高さ約25mの大きな門","鎌倉時代に再建された。大陸から入った大仏様という様式で、太い柱を貫で連結する構造が特徴。",34.6870,135.8393,"国宝")
s("興福寺 五重塔","tower",1426,"奈良市","","奈良のまちを見守る五重塔","約50mの塔で、奈良公園のシンボル。五重塔の中では、東寺に次いで高い。",34.6828,135.8333,"国宝")
s("唐招提寺 金堂","tower",780,"奈良市","","奈良時代の寄棟屋根の金堂","柱が8本並ぶ正面の列柱が印象的。大規模な修理が終わり、屋根の瓦も新しくなった。",34.6757,135.7845,"国宝")
s("薬師寺 東塔","tower",730,"奈良市","","凍れる音楽と呼ばれる三重塔","三重の塔だが、各層に小さな屋根があって六重に見える。創建当時から残る唯一の建物。",34.6692,135.7845,"国宝")
s("法隆寺 五重塔","tower",700,"斑鳩町","","世界最古の木造建築群の塔","7世紀末ごろの建築と考えられる。世界で最も古い木造建築の群の中心。中心を貫く心柱が、地震や強風に耐える。",34.6145,135.7340,"世界遺産",yl="飛鳥時代")
s("法隆寺 金堂","tower",700,"斑鳩町","","世界最古の木造建築","五重塔と並ぶ金堂。法隆寺の西院伽藍の中心で、柱の膨らみ（エンタシス）が特徴。",34.6143,135.7338,"世界遺産",yl="飛鳥時代")
s("室生寺 五重塔","tower",800,"宇陀市","","屋外にある最小の五重塔","高さ約16mで、屋外の五重塔としては国内で最も小さい。山中の木々の間に建つ。",34.5340,136.0470,"国宝",yl="平安時代初期")
s("談山神社 十三重塔","tower",1532,"桜井市","","現存する唯一の木造十三重塔","山の紅葉の中に建つ塔。十三の層が重なる姿は、他に例がない。",34.4755,135.8590,"重文")
s("當麻寺 東塔・西塔","tower",800,"葛城市","","東西で対になって残る三重塔","奈良時代と平安時代の三重塔が、東と西に対になって残る。ほぼ原形のまま残る貴重な例。",34.5110,135.7130,"国宝",yl="奈良〜平安時代")
s("長谷寺 本堂","tower",1650,"桜井市","徳川家光","崖に建つ舞台造の本堂","長い登廊を上った先に建つ。崖に張り出した舞台造で、国宝に指定されている。",34.5360,135.9090,"国宝")
s("金峯山寺 蔵王堂","tower",1592,"吉野町","","吉野山の木造大建築","高さ約34mの木造建築で、東大寺の大仏殿に次ぐ規模。桜の吉野山にそびえる。",34.3660,135.8590,"国宝")
s("平城宮跡 朱雀門","post",1998,"奈良市","文化庁","平城京の正門を復原","平城京の南の入口の門を復原した。発掘調査で得られた情報をもとに、当時の技術で建てた。",34.6853,135.7985)
s("平城宮跡 第一次大極殿","post",2010,"奈良市","文化庁","平城宮の中心の建物の復原","平城宮の正殿として復原された。柱や屋根に当時の工法を再現している。",34.6912,135.7957)
s("奈良ホテル","modern",1909,"奈良市","辰野金吾","洋風と和風が合わさったクラシックホテル","辰野金吾が設計した、日本の古建築の意匠を取り入れた洋風のホテル。",34.6783,135.8395)
s("奈良国立博物館 なら仏像館","modern",1894,"奈良市","片山東熊","フランス風ルネサンス様式の建物","奈良公園の中にあり、仏像を展示する施設として使われている。",34.6842,135.8370,"重文")
s("旧奈良駅舎","rail",1934,"奈良市","鉄道省","和風の屋根をもつ駅舎","瓦屋根を載せた和風の駅舎で、現在は観光案内所などになっている。",34.6813,135.8187)
s("旧奈良監獄（奈良少年刑務所）","modern",1908,"奈良市","山下啓次郎","れんが造の旧監獄","明治期の五大監獄のひとつ。れんが造の建物が現在はホテルなどとして再生されている。",34.6925,135.8350,"重文")
s("大和郡山城 天守台","port",1585,"大和郡山市","豊臣秀長","石垣に転用された石が見られる城跡","地蔵や石塔など、石材が石垣に転用されている。逆さ地蔵が有名。",34.6490,135.7810)
